}

#[no_predicates]
pub fn hash_15(input: [Field; 15]) -> Field {
    hash_internal(input, perm::x5_16)
}

#[no_predicates]
pub fn hash_16(input: [Field; 16]) -> Field {
    hash_internal(input, perm::x5_17)
}

